function PageHero({eye,title,text,image,alt=''}){return <section className="page-hero"><div><Eye>{eye}</Eye><h1>{title}</h1><p>{text}</p></div>{image&&<img src={image} alt={alt}/>}</section>}
function CohortFeature(){return <section className="section cohort-feature"><div className="cohort-feature-image"><img src={activityImages.fellows} alt="CyberAmbassador 2026 cohort flyer showing 18 fellows"/></div><div><Intro eye="CyberAmbassador 2026" title="18 young people. One safer digital future." text="The cohort flyer gives a face to the work: young people learning to protect, lead and inspire their communities through practical digital citizenship."/><div className="cohort-feature-facts"><span><b>18</b> fellows presented</span><span><b>2026</b> cohort</span><span><b>Lead · Protect · Inspire</b></span></div><Link page="cyberambassador" className="text-link">Meet the program <Arrow/></Link></div></section>}
function SectionBrowser(){return <nav className="section-browser" aria-label="Browse CyberAmbassador sections"><span>Explore the program</span>{[['Overview','cyber-overview'],['Platform','platform'],['Curriculum','curriculum'],['CyberA-Rise','cohort'],['Participant voices','voices'],['FAQ','cyber-faq']].map(x=><a key={x[1]} href={`#${x[1]}`}>{x[0]}</a>)}<a className="browser-cta" href={`${BASE}cyberambassador/`}>Open platform ↗</a></nav>}
function PlatformDetail(){let f=[['Guided learning','Sequential modules, lessons and quizzes turn a broad subject into a clear journey.'],['Practical missions','Investigations and challenges ask fellows to decide in recognisable situations.'],['Visible progression','Learners follow progress, badges, status and their route toward certification.'],['Connected support','Notifications, weekly reviews and the forum keep learning from becoming isolated.']];return <section className="platform-detail" id="platform"><div className="section platform-detail-inner"><div><Intro eye="A product built by Sykoti" title="A learning platform, not just a course page." text="CyberAmbassador has a dedicated digital environment designed around the full fellow experience—from the next lesson to practical action."/><a className="button primary" href={`${BASE}cyberambassador/`}>Access the learning platform <Arrow/></a></div><Browser src={`${BASE}program/dashboard-overview.png`} alt="CyberAmbassador fellow dashboard"/><div className="platform-features">{f.map((x,i)=><article key={x[0]}><b>0{i+1}</b><h3>{x[0]}</h3><p>{x[1]}</p></article>)}</div></div></section>}
function CohortDetail(){return <section className="section cohort-detail" id="cohort"><Intro eye="The first pilot cohort" title="CyberA-Rise: the program in real life." text="CyberA-Rise is the first implementation of CyberAmbassador. Fellows move through the same structured journey with regular reinforcement, feedback and opportunities to practise."/><div className="cohort-layout"><div className="cohort-portrait"><img src={cohort} alt="CyberA-Rise cohort participants"/><span>CyberA—Rise</span></div><div className="cohort-facts">{[['WHO','Selected young fellows','Different backgrounds united by curiosity, responsibility and the desire to help their communities.'],['HOW','Platform + human follow-up','Self-directed interactive learning reinforced through weekly sessions, questions and guidance.'],['WHAT','Learn, practise, lead, share','Four modules lead into missions, assessment, certification and community-minded action.'],['EVIDENCE','Feedback improves delivery','Participant reflections—including criticism of language and format—are treated as learning evidence.']].map(x=><article key={x[0]}><small>{x[0]}</small><h3>{x[1]}</h3><p>{x[2]}</p></article>)}</div></div></section>}
function Voices({home=false}){const[expanded,setExpanded]=useState({}),limit=145,shown=home?testimonials:testimonials.slice(0,5);return <section className={`voices${home?' home-voices':''}`} id="voices"><div className="section"><Intro eye="CyberA voices" title={home?'What CyberA participants say':'What fellows say about the experience'} text="Feedback shared by participants after their CyberComp experience."/><div className="voice-grid">{shown.map((x,i)=>{const long=x[1].length>limit,open=expanded[i],text=long&&!open?`${x[1].slice(0,limit).trim()}…`:x[1];return <blockquote key={x[0]}><span>{'★'.repeat(i?5:4)}</span><p>“{text}”</p>{long&&<button className="read-more" onClick={()=>setExpanded(e=>({...e,[i]:!e[i]}))}>{open?'Show less':'Read more'}</button>}<footer><i>{x[0][0]}</i><cite>{x[0]}</cite></footer></blockquote>})}</div></div></section>}
function People(){const people=[['Lesly Voumo','CyberA-Rise fellow','lesly-voumo.jpeg'],['Kouatchou Lyne Dehlia','CyberA-Rise fellow','kouatchou-lyne-dehlia.jpeg'],['Mokam Dora','CyberA-Rise fellow','mokam-dora.jpeg'],['Roxanna Moussombo','CyberA-Rise fellow','roxanna-moussombo.jpeg'],['Esther Ngono','CyberA-Rise fellow','esther-ngono.jpeg'],['Wilfried Adi Yafsia','CyberA-Rise fellow','wilfried-adi-yafsia.jpeg']];return <section className="section people-section"><Intro eye="People behind the work" title="A community made visible." text="Public profiles currently available from the CyberA-Rise cohort. Team and contributor biographies will be added as they are confirmed."/><div className="people-grid">{people.map(([name,role,file])=><article key={name}><img src={`${BASE}cyberambassador/media/${file}`} alt={`Portrait of ${name}`} loading="lazy"/><div><h3>{name}</h3><p>{role}</p></div></article>)}</div></section>}
function About({lang='en'}){const fr=lang==='fr';const roles=fr?[['Assemblée générale','Réunit les membres, délibère sur l’orientation, les rapports, les comptes et les élections.'],['Conseil d’administration','Autorise les actes et opérations de l’association, arrête le budget et veille à l’objet associatif.'],['Bureau exécutif','Présidence, fondateur, secrétariat général, trésorerie et conseillers assurent la conduite opérationnelle.'],['Cinq départements','Communication ; administration, finances et partenariats ; formation et mentorat ; technologie et innovation open source ; leadership, plaidoyer et service civique.']]:[['General Assembly','Brings members together to decide on direction, reports, accounts and elections.'],['Board of Directors','Authorises the organisation’s operations, sets the budget and safeguards its purpose.'],['Executive Office','The presidency, founder, general secretariat, treasury and advisers lead operations.'],['Five departments','Communication; administration, finance and partnerships; training and mentorship; technology and open-source innovation; leadership, advocacy and civic service.']];return <><section className="about-org-hero"><img src={activityImages.graduationGroup} alt={fr?'Communauté Sykoti Center réunie':'Sykoti Center community gathered'}/><div><p className="org-kicker">{fr?'À propos de Sykoti':'About Sykoti'}</p><h1>{fr?'Une association qui relie sécurité numérique, compétences pratiques et pouvoir d’agir.':'An association connecting digital safety, practical skills and agency.'}</h1></div></section><section className="about-org-story"><div><p className="org-kicker">{fr?'Notre origine':'Our origin'}</p><h2>{fr?'Répondre à plusieurs défis qui se renforcent mutuellement.':'Responding to challenges that reinforce one another.'}</h2></div><div><p>{fr?'Sykoti est née du constat que la progression de la connectivité ne suffit pas : les jeunes ont aussi besoin de repères face aux cybermenaces, d’occasions de pratiquer les STIM, d’un cadre pour innover et d’un accompagnement pour transformer leurs projets en solutions viables.':'Sykoti was created from the observation that connectivity alone is not enough: young people also need guidance on cyber threats, opportunities to practise STEM, space to innovate and support to turn projects into viable solutions.'}</p><dl><div><dt>{fr?'Statut':'Status'}</dt><dd>{fr?'Association camerounaise à but non lucratif et apolitique':'Cameroonian non-profit, non-political association'}</dd></div><div><dt>{fr?'Siège':'Head office'}</dt><dd>{fr?'Bafoussam, Région de l’Ouest, Cameroun':'Bafoussam, West Region, Cameroon'}</dd></div><div><dt>{fr?'Devise':'Motto'}</dt><dd>{fr?'Solidarité · Intégrité · Excellence':'Solidarity · Integrity · Excellence'}</dd></div><div><dt>{fr?'Président-fondateur':'Founding president'}</dt><dd>Ing. Ningha Catelle</dd></div></dl></div></section><section className="about-objectives"><div className="org-heading light-heading"><p className="org-kicker">{fr?'Objet de l’association':'Purpose of the association'}</p><h2>{fr?'Éduquer, faire pratiquer, accompagner et mobiliser.':'Educate, practise, support and mobilise.'}</h2></div><div className="about-objective-grid">{(fr?[['Numérique responsable','Citoyenneté en ligne, sensibilisation aux cybermenaces et initiation à la cybersécurité.'],['STIM pour toutes et tous','Usages pratiques des sciences et technologies, avec une attention aux filles et jeunes femmes.'],['Innovation','Encourager l’invention, l’expérimentation et le développement de solutions techniques.'],['Insertion & entrepreneuriat','Lutter contre l’inadéquation formation-emploi et accompagner les projets professionnels.'],['Jeunesse & service civique','Créer des alternatives utiles à l’oisiveté et soutenir l’engagement dans les communautés.']]:[['Responsible technology','Online citizenship, cyber-threat awareness and introductory cybersecurity learning.'],['STEM for everyone','Practical science and technology, with attention to girls and young women.'],['Innovation','Encourage invention, experimentation and technical solution development.'],['Employment & entrepreneurship','Address the training-employment gap and support professional projects.'],['Youth & civic service','Create constructive alternatives and support community engagement.']]).map((x,i)=><article key={x[0]}><b>0{i+1}</b><h3>{x[0]}</h3><p>{x[1]}</p></article>)}</div></section><section className="about-governance"><div className="org-heading"><p className="org-kicker">{fr?'Organisation & gouvernance':'Organisation & governance'}</p><h2>{fr?'Une structure associative, pas seulement une équipe projet.':'An association structure, not only a project team.'}</h2></div><div className="about-governance-grid">{roles.map((x,i)=><article key={x[0]}><span>0{i+1}</span><h3>{x[0]}</h3><p>{x[1]}</p></article>)}</div></section><section className="about-members"><div><p className="org-kicker">{fr?'La communauté associative':'The association community'}</p><h2>{fr?'Membres actifs, sympathisants et membres d’honneur.':'Active, supporting and honorary members.'}</h2></div><div><p>{fr?'Les membres actifs et sympathisants adhèrent aux statuts, participent aux activités et s’acquittent de la cotisation définie par l’Assemblée générale. Les membres actifs peuvent être élus et prennent des responsabilités dans l’association.':'Active and supporting members accept the statutes, participate in activities and pay the contribution defined by the General Assembly. Active members may stand for election and take responsibility in the association.'}</p><a className="button primary" href="mailto:contact@sykoticenter.com">{fr?'Demander les informations d’adhésion':'Request membership information'} <Arrow/></a></div></section></>}
function Programs({lang='en'}){const fr=lang==='fr';const[items,setItems]=useState([]),[loading,setLoading]=useState(true);useEffect(()=>{let active=true;fetch(`${API}/programs`).then(r=>r.ok?r.json():[]).then(async list=>{const detailed=await Promise.all(list.map(item=>fetch(`${API}/programs/${item.slug}`).then(r=>r.ok?r.json():{program:item,cohorts:[],activities:[]})));if(active)setItems(detailed)}).catch(()=>{}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[]);const fallback=[{program:{title:'CyberAmbassador',slug:'cyberambassador',summary:fr?'Parcours de formation et de leadership en citoyenneté et sécurité numériques.':'A digital citizenship, safety and leadership pathway.',audience:fr?'Jeunes sélectionnés':'Selected young people',statusLabel:fr?'Cohorte 2026 documentée':'2026 cohort documented',coverUrl:activityImages.communityAction},cohorts:[],activities:[]},{program:{title:fr?'100 bourses de formation':'100 Training Scholarships',slug:'100-scholarships',summary:fr?'Accès court et bilingue aux deux premiers modules du parcours.':'Short bilingual access to the first two pathway modules.',audience:'15–35',statusLabel:fr?'Édition 2026':'2026 edition',coverUrl:activityImages.platformModule},cohorts:[],activities:[]}],shown=items.length?items:fallback;return <><section className="content-hero"><div><p className="org-kicker">{fr?'Nos programmes':'Our programmes'}</p><h1>{fr?'Des parcours conçus pour apprendre et agir.':'Pathways designed for learning and action.'}</h1><p>{fr?'Chaque programme a un objectif, un public, un statut et des activités propres. Les nouvelles activités publiées depuis l’administration apparaissent ici.':'Each programme has its own purpose, audience, status and activities. New activities published from the admin appear here.'}</p></div></section><section className="program-catalogue">{loading&&<p>{fr?'Chargement…':'Loading…'}</p>}{shown.map(({program,cohorts,activities},i)=><article className="program-catalogue-item" key={program.slug}><img src={publicAsset(program.coverUrl)||activityImages.communityAction} alt=""/><div className="program-catalogue-copy"><span>0{i+1} · {program.statusLabel}</span><h2>{program.title}</h2><p>{program.summary}</p>{program.audience&&<strong>{fr?'Public :':'Audience:'} {program.audience}</strong>}<div className="program-catalogue-links">{program.slug==='cyberambassador'?<Link page="cyberambassador">{fr?'Voir le programme':'View programme'} <Arrow/></Link>:null}</div>{cohorts.length>0&&<div className="programme-cohorts"><h3>{fr?'Cohortes':'Cohorts'}</h3>{cohorts.map(c=><span key={c._id}>{c.name} · {c.statusLabel}</span>)}</div>}{activities.length>0&&<div className="programme-activities"><h3>{fr?'Activités récentes':'Recent activities'}</h3>{activities.slice(0,3).map(a=><div key={a._id}><b>{a.category}</b><span>{a.title}</span></div>)}</div>}</div></article>)}</section></>}
function Cyber(){return <CyberAmbassadorPage/>}
function Impact({lang='en'}){const fr=lang==='fr',{data}=usePublicData('/cyberambassador/impact',null);const stats=data?[{value:data.cyberA?.acceptedCount||0,label:fr?'participants retenus pour CyberA-Rise':'participants selected for CyberA-Rise'},{value:4,label:fr?'modules structurés':'structured modules'},{value:data.scholarships?.acceptedCount||0,label:fr?'admissions enregistrées pour les bourses':'recorded scholarship admissions'}]:impact;return <><section className="content-hero impact-hero"><div><p className="org-kicker">{fr?'Notre impact':'Our impact'}</p><h1>{fr?'Montrer ce qui a été réalisé, sans confondre activité et changement.':'Show what was delivered without confusing activity with change.'}</h1><p>{fr?'Cette page distingue les personnes sélectionnées, les apprentissages réalisés, les actions communautaires documentées et les effets qui restent à vérifier.':'This page separates selection, delivered learning, documented community action and outcomes that still require verification.'}</p></div></section><section className="impact-dashboard">{stats.map((x,i)=><article key={x.label}><span>0{i+1}</span><strong>{x.value}</strong><p>{x.label}</p></article>)}</section><section className="impact-evidence"><div className="org-heading"><p className="org-kicker">{fr?'Preuves disponibles':'Available evidence'}</p><h2>{fr?'Plateforme, cohorte, projets et suivi.':'Platform, cohort, projects and follow-up.'}</h2></div><div className="impact-evidence-grid"><figure><img src={activityImages.platformModule} alt=""/><figcaption>{fr?'Modules et progression sur la plateforme':'Modules and progression on the platform'}</figcaption></figure><figure><img src={activityImages.graduationGroup} alt=""/><figcaption>{fr?'Graduation de la cohorte 2026':'2026 cohort graduation'}</figcaption></figure><figure><img src={activityImages.communityAction} alt=""/><figcaption>{fr?'Actions réalisées dans les communautés':'Community activities delivered'}</figcaption></figure></div><div className="impact-method"><h3>{fr?'Comment lire ces données':'How to read this evidence'}</h3><p>{fr?'Les chiffres de participation ne sont pas additionnés comme des personnes uniques lorsque les mêmes personnes peuvent apparaître dans plusieurs étapes. Les témoignages et effets à moyen terme ne sont publiés qu’avec consentement et niveau de vérification explicite.':'Participation figures are not added as unique people when the same people may appear at several stages. Testimonials and medium-term outcomes are published only with consent and an explicit verification level.'}</p></div></section></>}
function Resources({lang='en'}){const fr=lang==='fr',{data:articles,loading}=usePublicData('/articles',[]),{data:reports}=usePublicData('/reports',[]),{data:webinars}=usePublicData('/webinars',[]);return <><section className="content-hero resources-hero"><div><p className="org-kicker">{fr?'Blog & ressources':'Blog & resources'}</p><h1>{fr?'Comprendre, apprendre et réutiliser.':'Understand, learn and reuse.'}</h1><p>{fr?'Articles, guides, rapports et conversations publiés par Sykoti Center depuis l’espace d’administration.':'Articles, guides, reports and conversations published by Sykoti Center from the admin workspace.'}</p></div></section><section className="published-resources"><div className="resource-section-heading"><h2>{fr?'Articles récents':'Latest articles'}</h2><span>{articles.length}</span></div>{loading?<p>{fr?'Chargement…':'Loading…'}</p>:articles.length?<div className="published-grid">{articles.map(a=><PublishedArticleCard key={a._id} article={a} lang={lang}/>)}</div>:<p className="empty-publication">{fr?'Aucun article publié pour le moment. Les articles publiés depuis l’administration apparaîtront ici.':'No articles have been published yet. Articles published from the admin will appear here.'}</p>}{reports.length>0&&<><div className="resource-section-heading"><h2>{fr?'Rapports & publications':'Reports & publications'}</h2><span>{reports.length}</span></div><div className="download-list">{reports.map(r=><a key={r._id} href={publicAsset(r.fileUrl)} target="_blank" rel="noreferrer"><span>{r.category}</span><strong>{r.title}</strong><small>{r.description}</small><b>↗</b></a>)}</div></>}{webinars.length>0&&<><div className="resource-section-heading"><h2>{fr?'Conversations & webinaires':'Conversations & webinars'}</h2><span>{webinars.length}</span></div><div className="webinar-grid">{webinars.map(w=><article key={w._id}><img src={publicAsset(w.coverUrl)||activityImages.webinar} alt=""/><h3>{w.title}</h3><p>{w.description}</p>{w.replayUrl&&<a href={w.replayUrl}>{fr?'Voir le replay':'Watch replay'} ↗</a>}</article>)}</div></>}</section></>}
function Partner(){return <><PageHero eye="Partner with Sykoti" title="Invest in safer digital communities." text="Fund, host, strengthen or help deliver practical digital citizenship and online-safety learning for young people." image={activityImages.graduationGroup} alt="CyberAmbassador fellows celebrating together"/><section className="section partner-models">{partnerships.map((x,i)=><article key={x[0]}><b>0{i+1}</b><h3>{x[0]}</h3><p>{x[1]}</p></article>)}</section><section className="contact-block"><div><Eye>Start a conversation</Eye><h2>Tell us what you want to make possible.</h2></div><a className="button light" href="mailto:contact@sykoticenter.com">contact@sykoticenter.com <Arrow/></a></section></>}
function ArticleDetail({slug,lang='en'}){const fr=lang==='fr',{data:article,loading,error}=usePublicData(`/articles/${slug}`,null),{data:all}=usePublicData('/articles',[]);if(loading)return <section className="article-state">{fr?'Chargement…':'Loading…'}</section>;if(error||!article)return <section className="article-state"><h1>{fr?'Article introuvable':'Article not found'}</h1><Link page="resources">{fr?'Retour aux ressources':'Back to resources'}</Link></section>;const date=article.publishedAt||article.createdAt,related=all.filter(x=>x.slug!==slug).slice(0,3);return <><article className="article-detail"><header><span>{article.category}</span><h1>{article.title}</h1><p>{article.excerpt}</p><div><b>{article.author||'Sykoti Center'}</b><time>{date&&new Intl.DateTimeFormat(fr?'fr-FR':'en-GB',{dateStyle:'long'}).format(new Date(date))}</time></div></header>{article.coverUrl&&<img className="article-cover" src={publicAsset(article.coverUrl)} alt=""/>}<div className="article-prose">{article.content.split(/\n+/).filter(Boolean).map((block,i)=>block.startsWith('## ')?<h2 key={i}>{block.slice(3)}</h2>:block.startsWith('# ')?<h2 key={i}>{block.slice(2)}</h2>:<p key={i}>{block}</p>)}</div></article>{related.length>0&&<section className="related-articles"><h2>{fr?'À lire ensuite':'Read next'}</h2><div className="published-grid">{related.map(a=><PublishedArticleCard key={a._id} article={a} lang={lang}/>)}</div></section>}</>}
function Contact({lang='en'}){const fr=lang==='fr',[form,setForm]=useState({name:'',email:'',subject:'',message:'',consent:false}),[state,setState]=useState({sending:false,error:'',sent:false});const change=(key,value)=>setForm(f=>({...f,[key]:value}));const submit=async e=>{e.preventDefault();setState({sending:true,error:'',sent:false});try{const response=await fetch(`${API}/contact`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)}),data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to send message');setState({sending:false,error:'',sent:true});setForm({name:'',email:'',subject:'',message:'',consent:false})}catch(error){setState({sending:false,error:error.message,sent:false})}};return <section className="contact-page"><div className="contact-intro"><p className="org-kicker">Contact</p><h1>{fr?'Parlons de votre question ou de votre projet.':'Let’s discuss your question or project.'}</h1><p>{fr?'Pour une adhésion, un partenariat, une activité, une intervention ou toute autre demande, écrivez-nous directement.':'For membership, partnerships, activities, speaking or any other request, write to us directly.'}</p><div className="contact-methods"><a href="mailto:contact@sykoticenter.com"><span>Email</span><strong>contact@sykoticenter.com</strong></a><div><span>{fr?'Siège':'Head office'}</span><strong>Bafoussam, Ouest Cameroun</strong></div></div></div><form className="contact-form" onSubmit={submit}><label>{fr?'Nom complet':'Full name'}<input required value={form.name} onChange={e=>change('name',e.target.value)}/></label><label>Email<input required type="email" value={form.email} onChange={e=>change('email',e.target.value)}/></label><label>{fr?'Objet':'Subject'}<input required value={form.subject} onChange={e=>change('subject',e.target.value)}/></label><label>{fr?'Message':'Message'}<textarea required minLength="10" value={form.message} onChange={e=>change('message',e.target.value)}/></label><label className="contact-consent"><input type="checkbox" required checked={form.consent} onChange={e=>change('consent',e.target.checked)}/><span>{fr?'J’accepte que Sykoti Center me contacte au sujet de ce message.':'I agree that Sykoti Center may contact me about this message.'}</span></label>{state.error&&<p className="form-error">{state.error}</p>}{state.sent&&<p className="form-success">{fr?'Votre message a bien été envoyé.':'Your message has been sent.'}</p>}<button className="button primary" disabled={state.sending}>{state.sending?(fr?'Envoi…':'Sending…'):(fr?'Envoyer le message':'Send message')} <Arrow/></button></form></section>}
function GetInvolved({lang='en'}){const fr=lang==='fr';return <><section className="content-hero involved-hero"><div><p className="org-kicker">{fr?'S’engager':'Get involved'}</p><h1>{fr?'Contribuer à Sykoti selon votre rôle et vos moyens.':'Contribute to Sykoti in a way that fits your role.'}</h1><p>{fr?'Adhésion, contribution bénévole, expertise ou partenariat : choisissez la voie qui correspond à votre intention.':'Membership, volunteering, expertise or partnership: choose the path that matches your intention.'}</p></div></section><section className="involved-grid"><article><span>01</span><h2>{fr?'Adhérer':'Become a member'}</h2><p>{fr?'Participer à la vie associative comme membre actif ou sympathisant, conformément aux statuts et au règlement intérieur.':'Take part in the association as an active or supporting member under its statutes and internal rules.'}</p><Link page="contact">{fr?'Demander les conditions':'Ask about membership'} <Arrow/></Link></article><article><span>02</span><h2>{fr?'Contribuer':'Contribute'}</h2><p>{fr?'Apporter du temps ou une compétence en formation, mentorat, technologie, communication, gestion ou service civique.':'Contribute time or expertise in training, mentoring, technology, communication, management or civic service.'}</p><Link page="contact">{fr?'Proposer une contribution':'Offer your contribution'} <Arrow/></Link></article><article><span>03</span><h2>{fr?'Devenir partenaire':'Become a partner'}</h2><p>{fr?'Soutenir, accueillir ou co-construire une initiative avec Sykoti Center.':'Support, host or co-develop an initiative with Sykoti Center.'}</p><Link page="contact">{fr?'Démarrer la conversation':'Start a conversation'} <Arrow/></Link></article></section></>}
function Footer({lang='en'}){const fr=lang==='fr';return <footer><div><Link page="home" className="brand"><img src={logo} alt="Sykoti Center"/><span>Sykoti <b>Center</b></span></Link><p>{fr?'Citoyenneté numérique, compétences pratiques, innovation et accompagnement des jeunes.':'Digital citizenship, practical skills, innovation and youth support.'}</p></div><div>{[[fr?'À propos':'About','about'],[fr?'Programmes':'Programmes','programs'],['CyberAmbassador','cyberambassador'],['Impact','impact'],[fr?'Blog & ressources':'Blog & resources','resources'],['Contact','contact'],[fr?'S’engager':'Get involved','get-involved']].map(x=><Link key={x[1]} page={x[1]}>{x[0]}</Link>)}</div><small>© {new Date().getFullYear()} Sykoti Center · Solidarité · Intégrité · Excellence</small></footer>}
export default function App(){const[page,setPage]=useState(current()),[lang,setLang]=useState(()=>localStorage.getItem('sykotiLanguage')||'en');const changeLang=value=>{setLang(value);localStorage.setItem('sykotiLanguage',value);document.documentElement.lang=value};const navigate=p=>{history.pushState({},'',path(p));setPage(p);scrollTo(0,0)};useEffect(()=>{document.documentElement.lang=lang},[lang]);useEffect(()=>{let f=()=>{setPage(current());scrollTo(0,0)};addEventListener('popstate',f);return()=>removeEventListener('popstate',f)},[]);useEffect(()=>{let n={home:'Sykoti Center',about:'About',programs:'Programmes',cyberambassador:'CyberAmbassador',impact:'Impact',resources:'Blog & Resources',article:'Article',contact:'Contact','get-involved':'Get involved',partner:'Partner With Us',engagement:'Prendre un engagement',wall:'Mur des engagements','evaluation-m1':'Évaluation M+1',reports:'2026 Reports',membership:'Membership application'};document.title=`Sykoti Center | ${n[page]}`},[page]);let v={home:<ReferenceHomeV2 lang={lang}/>,about:<><About lang={lang}/><TeamSection lang={lang}/></>,programs:<Programs lang={lang}/>,cyberambassador:<Cyber/>,impact:<Impact lang={lang}/>,resources:<Resources lang={lang}/>,article:<ArticleDetail slug={currentArticleSlug()} lang={lang}/>,contact:<Contact lang={lang}/>,'get-involved':<GetInvolved lang={lang}/>,partner:<GetInvolved lang={lang}/>,engagement:<EngagementPage navigate={navigate}/>,wall:<WallPage navigate={navigate}/>, 'evaluation-m1':<M1EvaluationPage/>};const referenceKey=page==='partner'?'get-involved':page,referencePages=['home','about','programs','impact','resources','get-involved','membership','reports','article','wall'];return referencePages.includes(referenceKey)?<ReferenceDocument page={referenceKey} slug={page==='article'?currentArticleSlug():''}/>:<div><Header page={page} lang={lang} setLang={changeLang}/><main>{v[page]}</main><Footer lang={lang}/></div>}
